     1→// 힙 메모리 관리 (Heap Memory Management)
     2→// Phase 5: 런타임
     3→
     4→use crate::value::Value;
     5→
     6→/// 힙 메모리 관리자
     7→#[derive(Debug, Clone)]
     8→pub struct Heap {
     9→    /// 메모리 저장소
    10→    memory: Vec<Value>,
    11→    /// 해제된 블록 (재사용 리스트)
    12→    free_list: Vec<usize>,
    13→}
    14→
    15→impl Heap {
    16→    /// 새 힙 생성
    17→    pub fn new() -> Self {
    18→        Heap {
    19→            memory: Vec::new(),
    20→            free_list: Vec::new(),
    21→        }
    22→    }
    23→
    24→    /// 메모리 할당
    25→    /// 새로운 값을 힙에 할당하고 주소를 반환합니다
    26→    pub fn allocate(&mut self, value: Value) -> usize {
    27→        // 해제된 블록이 있으면 재사용
    28→        if let Some(addr) = self.free_list.pop() {
    29→            self.memory[addr] = value;
    30→            addr
    31→        } else {
    32→            // 새 메모리 할당
    33→            let addr = self.memory.len();
    34→            self.memory.push(value);
    35→            addr
    36→        }
    37→    }
    38→
    39→    /// 메모리 해제
    40→    /// 주소의 값을 제거하고 블록을 해제 목록에 추가합니다
    41→    pub fn deallocate(&mut self, addr: usize) -> Result<(), String> {
    42→        if addr >= self.memory.len() {
    43→            return Err(format!("Invalid address: {}", addr));
    44→        }
    45→        self.free_list.push(addr);
    46→        Ok(())
    47→    }
    48→
    49→    /// 메모리에서 값 읽기
    50→    pub fn get(&self, addr: usize) -> Result<&Value, String> {
    51→        if addr >= self.memory.len() {
    52→            return Err(format!("Invalid address: {}", addr));
    53→        }
    54→        Ok(&self.memory[addr])
    55→    }
    56→
    57→    /// 메모리에 값 쓰기
    58→    pub fn set(&mut self, addr: usize, value: Value) -> Result<(), String> {
    59→        if addr >= self.memory.len() {
    60→            return Err(format!("Invalid address: {}", addr));
    61→        }
    62→        self.memory[addr] = value;
    63→        Ok(())
    64→    }
    65→
    66→    /// 힙 크기 (할당된 블록 수)
    67→    pub fn size(&self) -> usize {
    68→        self.memory.len()
    69→    }
    70→
    71→    /// 해제된 블록 수
    72→    pub fn free_count(&self) -> usize {
    73→        self.free_list.len()
    74→    }
    75→
    76→    /// 힙 초기화
    77→    pub fn clear(&mut self) {
    78→        self.memory.clear();
    79→        self.free_list.clear();
    80→    }
    81→
    82→    /// 전체 메모리 정리
    83→    pub fn gc(&mut self) {
    84→        // 간단한 GC: 해제된 블록을 실제로 제거하지 않음 (마킹만 함)
    85→        // 더 정교한 GC는 나중에 구현
    86→    }
    87→}
    88→
    89→impl Default for Heap {
    90→    fn default() -> Self {
    91→        Self::new()
    92→    }
    93→}
    94→
    95→#[cfg(test)]
    96→mod tests {
    97→    use super::*;
    98→
    99→    #[test]
   100→    fn test_heap_allocate() {
   101→        let mut heap = Heap::new();
   102→        let addr = heap.allocate(Value::Integer(42));
   103→        assert_eq!(addr, 0);
   104→        assert_eq!(heap.size(), 1);
   105→    }
   106→
   107→    #[test]
   108→    fn test_heap_get() {
   109→        let mut heap = Heap::new();
   110→        let addr = heap.allocate(Value::Integer(42));
   111→        let val = heap.get(addr).unwrap();
   112→        assert!(matches!(val, Value::Integer(42)));
   113→    }
   114→
   115→    #[test]
   116→    fn test_heap_set() {
   117→        let mut heap = Heap::new();
   118→        let addr = heap.allocate(Value::Integer(42));
   119→        heap.set(addr, Value::Integer(100)).unwrap();
   120→        let val = heap.get(addr).unwrap();
   121→        assert!(matches!(val, Value::Integer(100)));
   122→    }
   123→
   124→    #[test]
   125→    fn test_heap_deallocate() {
   126→        let mut heap = Heap::new();
   127→        let addr = heap.allocate(Value::Integer(42));
   128→        assert_eq!(heap.free_count(), 0);
   129→        heap.deallocate(addr).unwrap();
   130→        assert_eq!(heap.free_count(), 1);
   131→    }
   132→
   133→    #[test]
   134→    fn test_heap_deallocate_invalid() {
   135→        let mut heap = Heap::new();
   136→        let result = heap.deallocate(999);
   137→        assert!(result.is_err());
   138→    }
   139→
   140→    #[test]
   141→    fn test_heap_allocate_reuse() {
   142→        let mut heap = Heap::new();
   143→        let addr1 = heap.allocate(Value::Integer(42));
   144→        let addr2 = heap.allocate(Value::Integer(100));
   145→        assert_eq!(addr1, 0);
   146→        assert_eq!(addr2, 1);
   147→
   148→        heap.deallocate(addr1).unwrap();
   149→        let addr3 = heap.allocate(Value::String("hello".to_string()));
   150→        assert_eq!(addr3, 0); // 재사용된 주소
   151→    }
   152→
   153→    #[test]
   154→    fn test_heap_multiple_allocations() {
   155→        let mut heap = Heap::new();
   156→        let addr1 = heap.allocate(Value::Integer(1));
   157→        let addr2 = heap.allocate(Value::Integer(2));
   158→        let addr3 = heap.allocate(Value::Integer(3));
   159→
   160→        assert_eq!(addr1, 0);
   161→        assert_eq!(addr2, 1);
   162→        assert_eq!(addr3, 2);
   163→        assert_eq!(heap.size(), 3);
   164→    }
   165→
   166→    #[test]
   167→    fn test_heap_string_allocation() {
   168→        let mut heap = Heap::new();
   169→        let addr = heap.allocate(Value::String("hello world".to_string()));
   170→        let val = heap.get(addr).unwrap();
   171→        match val {
   172→            Value::String(s) => assert_eq!(s, "hello world"),
   173→            _ => panic!("Expected string"),
   174→        }
   175→    }
   176→
   177→    #[test]
   178→    fn test_heap_clear() {
   179→        let mut heap = Heap::new();
   180→        heap.allocate(Value::Integer(42));
   181→        heap.allocate(Value::Integer(100));
   182→        assert_eq!(heap.size(), 2);
   183→
   184→        heap.clear();
   185→        assert_eq!(heap.size(), 0);
   186→        assert_eq!(heap.free_count(), 0);
   187→    }
   188→
   189→    #[test]
   190→    fn test_heap_get_invalid() {
   191→        let heap = Heap::new();
   192→        let result = heap.get(999);
   193→        assert!(result.is_err());
   194→    }
   195→}
