     7→/// IR 노드는 AST를 더 낮은 수준의 표현으로 변환합니다
     8→#[derive(Debug, Clone, PartialEq)]
     9→pub enum IRNode {
    10→    // === 리터럴 값 ===
    11→    IntLiteral(i64),
    12→    FloatLiteral(f64),
    13→    StringLiteral(String),
    14→    BoolLiteral(bool),
    15→
    16→    // === 변수 ===
    17→    Variable(String),
    18→
    19→    // === 연산 ===
    20→    BinaryOp {
    21→        op: String,
    22→        left: Box<IRNode>,
    23→        right: Box<IRNode>,
    24→    },
    25→    UnaryOp {
    26→        op: String,
    27→        operand: Box<IRNode>,
    28→    },
    29→
    30→    // === 제어 흐름 ===
    31→    If {
    32→        condition: Box<IRNode>,
    33→        then_block: Vec<IRNode>,
    34→        else_block: Option<Vec<IRNode>>,
    35→    },
    36→
    37→    // === 함수 ===
    38→    FunctionCall {
    39→        name: String,
    40→        args: Vec<IRNode>,
    41→    },
    42→
    43→    // === 배열/튜플 ===
    44→    Array {
    45→        elements: Vec<IRNode>,
    46→    },
    47→    Index {
    48→        expr: Box<IRNode>,
    49→        index: Box<IRNode>,
    50→    },
    51→    Tuple {
    52→        elements: Vec<IRNode>,
    53→    },
    54→
    55→    // === 변수 할당 ===
    56→    Assign {
    57→        name: String,
    58→        value: Box<IRNode>,
    59→    },
    60→
    61→    // === 반환 ===
    62→    Return(Box<IRNode>),
    63→
    64→    // === 다중 명령 ===
    65→    Block(Vec<IRNode>),
    66→}
    67→
    68→/// IR 함수 정의
    69→#[derive(Debug, Clone)]
    70→pub struct IRFunction {
    71→    pub name: String,
    72→    pub params: Vec<(String, Type)>,
    73→    pub return_type: Type,
    74→    pub body: Vec<IRNode>,
    75→}
    76→
    77→/// IR 프로그램 (함수들의 모음)
    78→#[derive(Debug, Clone)]
    79→pub struct IRProgram {
    80→    pub functions: Vec<IRFunction>,
    81→    pub main: Vec<IRNode>,
    82→}
    83→
    84→impl IRNode {
    85→    /// 이 IR 노드가 값을 반환하는지 확인합니다
    86→    pub fn returns_value(&self) -> bool {
    87→        match self {
    88→            IRNode::IntLiteral(_)
    89→            | IRNode::FloatLiteral(_)
    90→            | IRNode::StringLiteral(_)
    91→            | IRNode::BoolLiteral(_)
    92→            | IRNode::Variable(_)
    93→            | IRNode::BinaryOp { .. }
    94→            | IRNode::UnaryOp { .. }
    95→            | IRNode::FunctionCall { .. }
    96→            | IRNode::Array { .. }
    97→            | IRNode::Index { .. }
    98→            | IRNode::Tuple { .. } => true,
    99→
   100→            IRNode::If { .. } | IRNode::Assign { .. } | IRNode::Return(_) | IRNode::Block(_) => {
   101→                false
   102→            }
   103→        }
   104→    }
   105→
   106→    /// 상수 폴딩: 컴파일 타임에 계산 가능한 상수 값들을 미리 계산합니다
   107→    pub fn fold_constants(&self) -> IRNode {
   108→        match self {
   109→            IRNode::BinaryOp { op, left, right } => {
   110→                let left_folded = left.fold_constants();
   111→                let right_folded = right.fold_constants();
   112→
   113→                // 두 피연산자가 모두 상수인 경우 계산
   114→                match (&left_folded, &right_folded) {
   115→                    (IRNode::IntLiteral(l), IRNode::IntLiteral(r)) => {
   116→                        match op.as_str() {
   117→                            "Plus" => IRNode::IntLiteral(l + r),
   118→                            "Minus" => IRNode::IntLiteral(l - r),
   119→                            "Star" => IRNode::IntLiteral(l * r),
   120→                            "Slash" if *r != 0 => IRNode::IntLiteral(l / r),
   121→                            "Percent" if *r != 0 => IRNode::IntLiteral(l % r),
   122→                            _ => IRNode::BinaryOp {
   123→                                op: op.clone(),
   124→                                left: Box::new(left_folded),
   125→                                right: Box::new(right_folded),
   126→                            },
   127→                        }
   128→                    }
   129→                    (IRNode::FloatLiteral(l), IRNode::FloatLiteral(r)) => {
   130→                        match op.as_str() {
   131→                            "Plus" => IRNode::FloatLiteral(l + r),
   132→                            "Minus" => IRNode::FloatLiteral(l - r),
   133→                            "Star" => IRNode::FloatLiteral(l * r),
   134→                            "Slash" => IRNode::FloatLiteral(l / r),
   135→                            _ => IRNode::BinaryOp {
   136→                                op: op.clone(),
   137→                                left: Box::new(left_folded),
   138→                                right: Box::new(right_folded),
   139→                            },
   140→                        }
   141→                    }
   142→                    _ => IRNode::BinaryOp {
   143→                        op: op.clone(),
   144→                        left: Box::new(left_folded),
   145→                        right: Box::new(right_folded),
   146→                    },
   147→                }
   148→            }
   149→            IRNode::UnaryOp { op, operand } => {
   150→                let operand_folded = operand.fold_constants();
   151→                match (&operand_folded, op.as_str()) {
   152→                    (IRNode::IntLiteral(n), "Minus") => IRNode::IntLiteral(-n),
   153→                    (IRNode::FloatLiteral(n), "Minus") => IRNode::FloatLiteral(-n),
   154→                    (IRNode::BoolLiteral(b), "Not") => IRNode::BoolLiteral(!b),
   155→                    _ => IRNode::UnaryOp {
   156→                        op: op.clone(),
   157→                        operand: Box::new(operand_folded),
   158→                    },
   159→                }
   160→            }
   161→            IRNode::If {
   162→                condition,
   163→                then_block,
   164→                else_block,
   165→            } => {
   166→                let condition_folded = condition.fold_constants();
   167→
   168→                // 조건이 상수인 경우 불필요한 분기 제거
   169→                match condition_folded {
   170→                    IRNode::BoolLiteral(true) => {
   171→                        let then_folded: Vec<_> =
   172→                            then_block.iter().map(|n| n.fold_constants()).collect();
   173→                        if then_folded.len() == 1 {
   174→                            then_folded[0].clone()
   175→                        } else {
   176→                            IRNode::Block(then_folded)
   177→                        }
   178→                    }
   179→                    IRNode::BoolLiteral(false) => {
   180→                        if let Some(else_stmts) = else_block {
   181→                            let else_folded: Vec<_> =
   182→                                else_stmts.iter().map(|n| n.fold_constants()).collect();
   183→                            if else_folded.len() == 1 {
   184→                                else_folded[0].clone()
   185→                            } else {
   186→                                IRNode::Block(else_folded)
   187→                            }
   188→                        } else {
   189→                            IRNode::Block(vec![])
   190→                        }
   191→                    }
   192→                    _ => IRNode::If {
   193→                        condition: Box::new(condition_folded),
   194→                        then_block: then_block.iter().map(|n| n.fold_constants()).collect(),
   195→                        else_block: else_block
   196→                            .as_ref()
   197→                            .map(|stmts| stmts.iter().map(|n| n.fold_constants()).collect()),
   198→                    },
   199→                }
   200→            }
   201→            IRNode::Block(nodes) => {
   202→                let folded: Vec<_> = nodes.iter().map(|n| n.fold_constants()).collect();
   203→                IRNode::Block(folded)
   204→            }
   205→            _ => self.clone(),
   206→        }
   207→    }
   208→
   209→    /// 불필요한 변수 할당을 제거합니다
   210→    pub fn eliminate_dead_code(&self) -> IRNode {
   211→        match self {
   212→            IRNode::Block(nodes) => {
   213→                let mut live_nodes = Vec::new();
   214→
   215→                for (i, node) in nodes.iter().enumerate() {
   216→                    match node {
   217→                        IRNode::Assign { name, value } => {
   218→                            // 다음 사용 위치를 찾습니다
   219→                            let is_used = nodes[i + 1..].iter().any(|n| {
   220→                                Self::uses_variable(n, name)
   221→                            });
   222→
   223→                            if is_used {
   224→                                live_nodes.push(node.eliminate_dead_code());
   225→                            }
   226→                            // 그렇지 않으면 제거합니다
   227→                        }
   228→                        _ => {
   229→                            live_nodes.push(node.eliminate_dead_code());
   230→                        }
   231→                    }
   232→                }
   233→
   234→                IRNode::Block(live_nodes)
   235→            }
   236→            IRNode::If {
   237→                condition,
   238→                then_block,
   239→                else_block,
   240→            } => IRNode::If {
   241→                condition: Box::new(condition.eliminate_dead_code()),
   242→                then_block: then_block.iter().map(|n| n.eliminate_dead_code()).collect(),
   243→                else_block: else_block
   244→                    .as_ref()
   245→                    .map(|stmts| stmts.iter().map(|n| n.eliminate_dead_code()).collect()),
   246→            },
   247→            _ => self.clone(),
   248→        }
   249→    }
   250→
   251→    /// 주어진 변수가 이 노드에서 사용되는지 확인합니다
   252→    fn uses_variable(node: &IRNode, name: &str) -> bool {
   253→        match node {
   254→            IRNode::Variable(n) => n == name,
   255→            IRNode::BinaryOp { left, right, .. } => {
   256→                Self::uses_variable(left, name) || Self::uses_variable(right, name)
   257→            }
   258→            IRNode::UnaryOp { operand, .. } => Self::uses_variable(operand, name),
   259→            IRNode::Index { expr, index } => {
   260→                Self::uses_variable(expr, name) || Self::uses_variable(index, name)
   261→            }
   262→            IRNode::If {
   263→                condition,
   264→                then_block,
   265→                else_block,
   266→            } => {
   267→                Self::uses_variable(condition, name)
   268→                    || then_block.iter().any(|n| Self::uses_variable(n, name))
   269→                    || else_block
   270→                        .as_ref()
   271→                        .map_or(false, |stmts| stmts.iter().any(|n| Self::uses_variable(n, name)))
   272→            }
   273→            IRNode::FunctionCall { args, .. } => {
   274→                args.iter().any(|arg| Self::uses_variable(arg, name))
   275→            }
   276→            IRNode::Array { elements } => elements.iter().any(|e| Self::uses_variable(e, name)),
   277→            IRNode::Tuple { elements } => elements.iter().any(|e| Self::uses_variable(e, name)),
   278→            IRNode::Block(nodes) => nodes.iter().any(|n| Self::uses_variable(n, name)),
   279→            _ => false,
   280→        }
   281→    }
   282→}
