   284→impl fmt::Display for IRNode {
   285→    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
   286→        match self {
   287→            IRNode::IntLiteral(n) => write!(f, "{}", n),
   288→            IRNode::FloatLiteral(n) => write!(f, "{}", n),
   289→            IRNode::StringLiteral(s) => write!(f, "\"{}\"", s),
   290→            IRNode::BoolLiteral(b) => write!(f, "{}", b),
   291→            IRNode::Variable(name) => write!(f, "{}", name),
   292→            IRNode::BinaryOp { op, left, right } => {
   293→                write!(f, "({} {} {})", left, op, right)
   294→            }
   295→            IRNode::UnaryOp { op, operand } => write!(f, "({} {})", op, operand),
   296→            IRNode::If {
   297→                condition,
   298→                then_block,
   299→                else_block,
   300→            } => {
   301→                write!(f, "if ({}) {{ ", condition)?;
   302→                for stmt in then_block {
   303→                    write!(f, "{}; ", stmt)?;
   304→                }
   305→                write!(f, "}}")?;
   306→                if let Some(else_stmts) = else_block {
   307→                    write!(f, " else {{ ")?;
   308→                    for stmt in else_stmts {
   309→                        write!(f, "{}; ", stmt)?;
   310→                    }
   311→                    write!(f, "}}")?;
   312→                }
   313→                Ok(())
   314→            }
   315→            IRNode::FunctionCall { name, args } => {
   316→                write!(f, "{}(", name)?;
   317→                for (i, arg) in args.iter().enumerate() {
   318→                    if i > 0 {
   319→                        write!(f, ", ")?;
   320→                    }
   321→                    write!(f, "{}", arg)?;
   322→                }
   323→                write!(f, ")")
   324→            }
   325→            IRNode::Array { elements } => {
   326→                write!(f, "[")?;
   327→                for (i, elem) in elements.iter().enumerate() {
   328→                    if i > 0 {
   329→                        write!(f, ", ")?;
   330→                    }
   331→                    write!(f, "{}", elem)?;
   332→                }
   333→                write!(f, "]")
   334→            }
   335→            IRNode::Index { expr, index } => write!(f, "{}[{}]", expr, index),
   336→            IRNode::Tuple { elements } => {
   337→                write!(f, "(")?;
   338→                for (i, elem) in elements.iter().enumerate() {
   339→                    if i > 0 {
   340→                        write!(f, ", ")?;
   341→                    }
   342→                    write!(f, "{}", elem)?;
   343→                }
   344→                write!(f, ")")
   345→            }
   346→            IRNode::Assign { name, value } => write!(f, "{} = {}", name, value),
   347→            IRNode::Return(expr) => write!(f, "return {}", expr),
   348→            IRNode::Block(nodes) => {
   349→                write!(f, "{{ ")?;
   350→                for node in nodes {
   351→                    write!(f, "{}; ", node)?;
   352→                }
   353→                write!(f, "}}")
   354→            }
   355→        }
   356→    }
   357→}
