     1→// 호출 스택 관리 (Call Stack Management)
     2→// Phase 5: 런타임
     3→
     4→use crate::value::Value;
     5→use std::collections::HashMap;
     6→
     7→/// 스택 프레임 (함수 호출 하나 = 하나의 프레임)
     8→#[derive(Debug, Clone)]
     9→pub struct StackFrame {
    10→    /// 지역 변수 저장소
    11→    pub variables: HashMap<String, Value>,
    12→    /// 반환 주소 (현재는 프로그램 카운터)
    13→    pub return_address: usize,
    14→    /// 지역 메모리 크기
    15→    pub local_size: usize,
    16→    /// 함수 이름 (디버깅용)
    17→    pub function_name: String,
    18→}
    19→
    20→impl StackFrame {
    21→    /// 새 스택 프레임 생성
    22→    pub fn new(function_name: String, return_address: usize) -> Self {
    23→        StackFrame {
    24→            variables: HashMap::new(),
    25→            return_address,
    26→            local_size: 0,
    27→            function_name,
    28→        }
    29→    }
    30→
    31→    /// 변수 저장
    32→    pub fn set_var(&mut self, name: String, value: Value) {
    33→        self.variables.insert(name, value);
    34→    }
    35→
    36→    /// 변수 읽기
    37→    pub fn get_var(&self, name: &str) -> Option<Value> {
    38→        self.variables.get(name).cloned()
    39→    }
    40→
    41→    /// 변수 존재 확인
    42→    pub fn has_var(&self, name: &str) -> bool {
    43→        self.variables.contains_key(name)
    44→    }
    45→
    46→    /// 모든 변수 개수
    47→    pub fn var_count(&self) -> usize {
    48→        self.variables.len()
    49→    }
    50→}
    51→
    52→/// 호출 스택
    53→#[derive(Debug, Clone)]
    54→pub struct Stack {
    55→    /// 스택 프레임들
    56→    frames: Vec<StackFrame>,
    57→}
    58→
    59→impl Stack {
    60→    /// 새 스택 생성 (글로벌 프레임 포함)
    61→    pub fn new() -> Self {
    62→        let mut stack = Stack {
    63→            frames: Vec::new(),
    64→        };
    65→        // 글로벌 프레임 추가
    66→        stack.frames.push(StackFrame::new("global".to_string(), 0));
    67→        stack
    68→    }
    69→
    70→    /// 프레임 푸시
    71→    pub fn push_frame(&mut self, frame: StackFrame) {
    72→        self.frames.push(frame);
    73→    }
    74→
    75→    /// 프레임 팝
    76→    pub fn pop_frame(&mut self) -> Result<StackFrame, String> {
    77→        if self.frames.len() <= 1 {
    78→            return Err("Cannot pop global frame".to_string());
    79→        }
    80→        self.frames.pop().ok_or_else(|| "Stack underflow".to_string())
    81→    }
    82→
    83→    /// 현재 프레임 (가장 위의 프레임)
    84→    pub fn current_frame(&self) -> Option<&StackFrame> {
    85→        self.frames.last()
    86→    }
    87→
    88→    /// 현재 프레임 (가변)
    89→    pub fn current_frame_mut(&mut self) -> Option<&mut StackFrame> {
    90→        self.frames.last_mut()
    91→    }
    92→
    93→    /// 현재 프레임에 변수 저장
    94→    pub fn set_var(&mut self, name: String, value: Value) -> Result<(), String> {
    95→        if let Some(frame) = self.frames.last_mut() {
    96→            frame.set_var(name, value);
    97→            Ok(())
    98→        } else {
    99→            Err("No active frame".to_string())
   100→        }
   101→    }
   102→
   103→    /// 변수 읽기 (현재 프레임에서 시작, 글로벌까지 탐색)
   104→    pub fn get_var(&self, name: &str) -> Option<Value> {
   105→        // 현재 프레임부터 글로벌 프레임까지 역순 탐색
   106→        for i in (0..self.frames.len()).rev() {
   107→            if let Some(value) = self.frames[i].get_var(name) {
   108→                return Some(value);
   109→            }
   110→        }
   111→        None
   112→    }
   113→
   114→    /// 변수가 존재하는지 확인
   115→    pub fn has_var(&self, name: &str) -> bool {
   116→        self.frames.iter().any(|f| f.has_var(name))
   117→    }
   118→
   119→    /// 스택 깊이 (프레임 개수)
   120→    pub fn depth(&self) -> usize {
   121→        self.frames.len()
   122→    }
   123→
   124→    /// 스택 비우기
   125→    pub fn clear(&mut self) {
   126→        self.frames.clear();
   127→        self.frames.push(StackFrame::new("global".to_string(), 0));
   128→    }
   129→
   130→    /// 글로벌 변수 저장 (글로벌 프레임에만)
   131→    pub fn set_global_var(&mut self, name: String, value: Value) -> Result<(), String> {
   132→        if let Some(frame) = self.frames.first_mut() {
   133→            frame.set_var(name, value);
   134→            Ok(())
   135→        } else {
   136→            Err("No global frame".to_string())
   137→        }
   138→    }
   139→
   140→    /// 글로벌 변수 읽기
   141→    pub fn get_global_var(&self, name: &str) -> Option<Value> {
   142→        if let Some(frame) = self.frames.first() {
   143→            frame.get_var(name)
   144→        } else {
   145→            None
   146→        }
   147→    }
   148→}
   149→
   150→impl Default for Stack {
   151→    fn default() -> Self {
   152→        Self::new()
   153→    }
   154→}
