     2→// Phase 4: 코드 생성 (AST → IR → Code)
     3→
     4→use crate::ast::*;
     5→use crate::ir::*;
     6→use crate::types::Type;
     7→use crate::CompileError;
     8→use std::collections::HashMap;
     9→
    10→/// 코드 생성기
    11→pub struct CodeGenerator {
    12→    indent_level: usize,
    13→    current_label: usize,
    14→    function_map: HashMap<String, IRFunction>,
    15→}
    16→
    17→impl CodeGenerator {
    18→    /// 새로운 코드 생성기를 생성합니다
    19→    pub fn new() -> Self {
    20→        CodeGenerator {
    21→            indent_level: 0,
    22→            current_label: 0,
    23→            function_map: HashMap::new(),
    24→        }
    25→    }
    26→
    27→    /// 프로그램을 생성합니다 (기존 호환성 유지)
    28→    pub fn generate(&self, program: &Program) -> Result<String, CompileError> {
    29→        let mut output = String::new();
    30→        output.push_str("// FV-Lang compiled output\n\n");
    31→
    32→        for def in &program.definitions {
    33→            match def {
    34→                Definition::Function { name, params, body } => {
    35→                    output.push_str(&format!("fn {}(", name));
    36→                    for (i, param) in params.iter().enumerate() {
    37→                        if i > 0 {
    38→                            output.push_str(", ");
    39→                        }
    40→                        output.push_str(&format!("{}: unknown", param));
    41→                    }
    42→                    output.push_str(") -> unknown {\n");
    43→
    44→                    for stmt in body {
    45→                        output.push_str(&self.generate_statement(stmt)?);
    46→                    }
    47→
    48→                    output.push_str("}\n\n");
    49→                }
    50→                Definition::TypeDef { name } => {
    51→                    output.push_str(&format!("type {};\n", name));
    52→                }
    53→            }
    54→        }
    55→
    56→        Ok(output)
    57→    }
    58→
    59→    /// 프로그램을 IR로 변환합니다
    60→    pub fn ast_to_ir(&mut self, program: &Program) -> Result<IRProgram, CompileError> {
    61→        let mut functions = Vec::new();
    62→
    63→        // 함수 정의 처리
    64→        for definition in &program.definitions {
    65→            match definition {
    66→                Definition::Function { name, params, body } => {
    67→                    let ir_body: Vec<_> = body
    68→                        .iter()
    69→                        .map(|stmt| self.statement_to_ir(stmt))
    70→                        .collect::<Result<Vec<_>, _>>()?;
    71→
    72→                    let ir_func = IRFunction {
    73→                        name: name.clone(),
    74→                        params: params
    75→                            .iter()
    76→                            .map(|p| (p.clone(), Type::Unknown))
    77→                            .collect(),
    78→                        return_type: Type::Unknown,
    79→                        body: ir_body,
    80→                    };

